use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Semaphore {
    permits: Mutex<u32>,
    cv: Condvar,
}

impl Semaphore {
    fn new(count: u32) -> Self {
        Self {
            permits: Mutex::new(count),
            cv: Condvar::new(),
        }
    }

    fn acquire(&self) {
        cir_trace::ev("t0", "s1");
        let mut permits = self.permits.lock().unwrap();
        while *permits == 0 {
            cir_trace::ev("t0", "s2");
            permits = self.cv.wait(permits).unwrap();
        }
        *permits -= 1;
    }

    fn release(&self) {
        cir_trace::ev("t0", "s3");
        *self.permits.lock().unwrap() += 1;
        cir_trace::ev("t0", "s4");
        self.cv.notify_one();
    }
}

fn main() {
    let mtx_a = Arc::new(Mutex::new(()));
    let mtx_b = Arc::new(Mutex::new(()));
    let sem_a = Arc::new(Semaphore::new(0));
    let sem_b = Arc::new(Semaphore::new(0));

    let (ma, mb, sa, sb) = (
        Arc::clone(&mtx_a),
        Arc::clone(&mtx_b),
        Arc::clone(&sem_a),
        Arc::clone(&sem_b),
    );
    cir_trace::ev("t0", "s5");
    let worker_a = thread::spawn(move || {
        cir_trace::ev("t0", "s6");
        let ga = ma.lock().unwrap();
        cir_trace::ev("t0", "s7");
        sa.release();
        cir_trace::ev("t0", "s8");
        sb.acquire();
        cir_trace::ev("t0", "s9");
        let gb = mb.lock().unwrap();
        cir_trace::ev("t0", "s10");
        drop(gb);
        cir_trace::ev("t0", "s11");
        drop(ga);
    });

    let (ma2, mb2, sa2, sb2) = (
        Arc::clone(&mtx_a),
        Arc::clone(&mtx_b),
        Arc::clone(&sem_a),
        Arc::clone(&sem_b),
    );
    cir_trace::ev("t0", "s12");
    let worker_b = thread::spawn(move || {
        cir_trace::ev("t0", "s13");
        let gb = mb2.lock().unwrap();
        cir_trace::ev("t0", "s14");
        sb2.release();
        cir_trace::ev("t0", "s15");
        sa2.acquire();
        cir_trace::ev("t0", "s16");
        let ga = ma2.lock().unwrap();
        cir_trace::ev("t0", "s17");
        drop(ga);
        cir_trace::ev("t0", "s18");
        drop(gb);
    });

    cir_trace::ev("t0", "s19");
    let progress = thread::spawn(move || loop {
        cir_trace::ev("t0", "s20");
        std::hint::spin_loop();
    });

    cir_trace::ev("t0", "s21");
    worker_a.join().unwrap();
    cir_trace::ev("t0", "s22");
