        // begin acquiring locks until A is finished with them.
        cir_trace::ev("t0", "s4");
        sb.release();
        cir_trace::ev("t0", "s5");
        drop(gb);
        cir_trace::ev("t0", "s6");
        drop(ga);
        cir_trace::ev("t0", "s7");
    });

