use std::sync::{Arc, Condvar, Mutex};
use std::thread;

fn main() {
    cir_trace::ev("t0", "s1");
    let pair = Arc::new((Mutex::new(false), Condvar::new()));

    let pair_w = Arc::clone(&pair);
    let waiter = thread::spawn(move || {
        let (mtx, cv) = &*pair_w;
        cir_trace::ev("t0", "s6");
        let mut guard = mtx.lock().unwrap();

        cir_trace::ev("t0", "s7");
        while !*guard {
            cir_trace::ev("t0", "s8");
            guard = cv.wait(guard).unwrap();
            cir_trace::ev("t0", "s9");
        }
        cir_trace::ev("t0", "s10");
        drop(guard);
        cir_trace::ev("t0", "s11");
    });

    cir_trace::ev("t0", "s2");
    let pair_n = Arc::clone(&pair);
    let notifier = thread::spawn(move || {
        let (mtx, cv) = &*pair_n;
        cir_trace::ev("t0", "s12");
        let mut ready = mtx.lock().unwrap();
        cir_trace::ev("t0", "s13");
        *ready = true;
        cir_trace::ev("t0", "s14");
        cv.notify_all();
        cir_trace::ev("t0", "s15");
        drop(ready);
        cir_trace::ev("t0", "s16");
    });

    cir_trace::ev("t0", "s3");
    waiter.join().unwrap();
    cir_trace::ev("t0", "s4");
    notifier.join().unwrap();
    cir_trace::ev("t0", "s5");
    cir_trace::finish();
}
